from sqlalchemy import *
from sqlalchemy.types import Uuid
metadata=MetaData()
metric_definitions=Table("metric_definitions",metadata,Column("metric_id",Uuid,primary_key=True),Column("canonical_name",String,unique=True,nullable=False),Column("unit",String,nullable=False),Column("value_kind",String,nullable=False),Column("is_flow",Boolean,nullable=False))
source_mappings=Table("fundamental_source_mappings",metadata,Column("mapping_id",Uuid,primary_key=True),Column("source",String,nullable=False),Column("source_field",String,nullable=False),Column("metric_id",Uuid,ForeignKey("metric_definitions.metric_id"),nullable=False),Column("source_unit",String,nullable=False),Column("scale",Numeric,nullable=False),UniqueConstraint("source","source_field"))
filings=Table("filings",metadata,Column("filing_id",Uuid,primary_key=True),Column("instrument_id",Uuid,nullable=False),Column("source",String,nullable=False),Column("source_filing_id",String,nullable=False),Column("revision",String,nullable=False),Column("report_type",String,nullable=False),Column("period_end",Date,nullable=False),Column("announced_at",DateTime(timezone=True),nullable=False),Column("available_at",DateTime(timezone=True),nullable=False),Column("ingested_at",DateTime(timezone=True),nullable=False),Column("raw_uri",String,nullable=False),Column("payload_hash",String,nullable=False),Column("status",String,nullable=False),UniqueConstraint("source","source_filing_id","revision"),CheckConstraint("available_at >= announced_at"))
facts=Table("fundamental_facts",metadata,Column("fact_id",Uuid,primary_key=True),Column("filing_id",Uuid,ForeignKey("filings.filing_id"),nullable=False),Column("instrument_id",Uuid,nullable=False),Column("metric_id",Uuid,ForeignKey("metric_definitions.metric_id"),nullable=False),Column("period_end",Date,nullable=False),Column("period_type",String,nullable=False),Column("source",String,nullable=False),Column("revision",String,nullable=False),Column("value",Numeric),Column("unit",String,nullable=False),Column("currency",String),Column("raw_value",String),Column("lineage",JSON,nullable=False),UniqueConstraint("instrument_id","metric_id","period_end","period_type","source","revision"))
quality=Table("fundamental_quality_results",metadata,Column("result_id",Uuid,primary_key=True),Column("source",String,nullable=False),Column("source_filing_id",String,nullable=False),Column("revision",String,nullable=False),Column("code",String,nullable=False),Column("message",String,nullable=False),Column("field",String))
events=Table("fundamental_revision_events",metadata,Column("event_id",Uuid,primary_key=True),Column("filing_id",Uuid,ForeignKey("filings.filing_id"),nullable=False),Column("instrument_id",Uuid,nullable=False),Column("old_revision",String),Column("new_revision",String,nullable=False),Column("affected",JSON,nullable=False),Column("occurred_at",DateTime(timezone=True),nullable=False))
share_capital_changes=Table("share_capital_changes",metadata,Column("change_id",Uuid,primary_key=True),Column("instrument_id",Uuid,nullable=False),Column("effective_date",Date,nullable=False),Column("total_shares",Numeric,nullable=False),Column("float_shares",Numeric,nullable=False),Column("source",String,nullable=False),Column("announced_at",DateTime(timezone=True),nullable=False),Column("available_at",DateTime(timezone=True),nullable=False),UniqueConstraint("instrument_id","effective_date","source"),CheckConstraint("total_shares > 0 AND float_shares >= 0 AND float_shares <= total_shares"),CheckConstraint("available_at >= announced_at"))
